def check_prompt(guards: list[InputGuardrail], text: str) -> str:
    for g in guards:
        d = g.evaluate(text, {"user_role": "customer"})
        if d.action == "block":
            raise PermissionError(f"{g.name}: {d.reason}")
        if d.action == "redact" and d.redacted_text is not None:
            text = d.redacted_text
    return text
